        ComprehensionStory(id = "1_1", grade = 1, title = "Лодочка", text = "Пришла тёплая весна. Потекла вода. Дети взяли дощечки и сделали лодочку. Лодка плыла по воде. Дети бежали за ней и весело кричали. Они не смотрели под ноги. Дети попали в лужу. Лодочка уплыла далеко. Мальчики и девочки промокли, но им было весело. Они вернулись домой и рассказали маме о своём приключении. Мама покачала головой, но не стала ругать. Она дала им сухую одежду и горячий чай.", questions = listOf("Что сделали дети из дощечек?", "Почему дети попали в лужу?", "Куда уплыла лодочка?", "Как мама встретила детей дома?")),
        ComprehensionStory(id = "1_2", grade = 1, title = "Тёплое место", text = "Зимой на улице было очень холодно. Вова и Маша гуляли во дворе. Вдруг они увидели на снегу маленького воробья. Он не мог лететь, потому что замёрз. Ребята взяли его домой. Дома они посадили птичку в коробку и насыпали зёрен. Воробей согрелся, поел и стал весело чирикать. Весной дети выпустили его на волю. Воробей был очень благодарен ребятам за тёплое место.", questions = listOf("Кого увидели дети на снегу?", "Почему воробей не мог лететь?", "Что ребята сделали дома?", "Когда дети выпустили птичку?")),
        ComprehensionStory(id = "1_3", grade = 1, title = "Два семечка", text = "Весной ветер принёс два семечка. Одно упало на дорогу, а другое в мягкую землю. Дождик поливал землю. Солнышко грело. Из земли выросло маленькое деревце. А семечко на дороге склевали птицы. Теперь деревце растёт и радует всех. Оно шелестит листьями и даёт тень в жаркий день.", questions = listOf("Что принёс ветер?", "Куда упали семечки?", "Почему выросло деревце?", "Что случилось с семечком на дороге?")),
        ComprehensionStory(id = "1_4", grade = 1, title = "Синяя пуговица", text = "Утром Саша собирался в школу. Он надевал свою любимую синюю рубашку. Вдруг мальчик заметил, что на рукаве не хватает одной пуговицы. Саша очень расстроился. Он начал искать пуговицу по всей комнате. Но пуговицы нигде не было. Тогда Саша вспомнил, что вчера играл во дворе. Он выбежал на улицу и нашёл пуговицу возле скамейки.", questions = listOf("Почему Саша расстроился?", "Где мальчик искал пуговицу?", "Куда Саша побежал искать?", "Где нашлась пуговица?")),
        ComprehensionStory(id = "1_5", grade = 1, title = "Чашка с кораблём", text = "У бабушки на полке стояла белая чашка. На ней был нарисован парусный корабль. Однажды внук Петя играл с мячом и случайно задел полку. Чашка упала и разбилась. Петя испугался и заплакал. Бабушка пришла на шум. Она обняла внука и сказала, что главное — он не поранился. Бабушка собрала осколки. Петя понял, что нужно быть осторожным.", questions = listOf("Что было нарисовано на чашке?", "Как разбилась чашка?", "Как бабушка отреагировала?", "Какой урок вынес Петя?")),
        ComprehensionStory(id = "1_6", grade = 1, title = "Дорожка в снегу", text = "Утром выпал пушистый снег. Катя вышла во двор. Она шла и оставляла на снегу ровные следы. Потом прибежал кот Барсик. Он тоже оставил следы, но они были круглые и маленькие. Катя нашла дорожку кота и пошла по ней. За сугробом она увидела Барсика. Он сидел и смотрел на птицу.", questions = listOf("Когда выпал снег?", "Кто вышел во двор?", "Чьи следы нашла Катя?", "Кого увидел Барсик?")),
        ComprehensionStory(id = "1_7", grade = 1, title = "Дом для зайца", text = "Наступила зима. Зайцу стало холодно в лесу. Он нашёл под ёлкой пустое дупло. Заяц натаскал туда сухих листьев и травы. Теперь у него есть тёплый дом. Но тут пришла лиса. Она хотела съесть зайца. Заяц быстро спрятался в дупле. Лиса не смогла его достать и ушла.", questions = listOf("Почему зайцу стало холодно?", "Что заяц нашёл под ёлкой?", "Кто пришёл к дуплу?", "Почему лиса ушла ни с чем?")),
        ComprehensionStory(id = "1_8", grade = 1, title = "Шарф для снеговика", text = "Дети лепили во дворе снеговика. Снеговик получился большой и весёлый. Но ему было холодно. Маша решила подарить снеговику шарф. Она принесла красный шарф и завязала его снеговику. Теперь снеговик стоял нарядный и улыбался. Дети были очень рады. Они играли возле снеговика до самого вечера.", questions = listOf("Кого лепили дети?", "Что Маша подарила снеговику?", "Какого цвета был шарф?", "До какого времени дети играли?")),
        ComprehensionStory(id = "1_9", grade = 1, title = "Зелёный флажок", text = "Каждое лето я отдыхаю у бабушки в деревне. Однажды мы с друзьями построили крепость из веток. К вечеру стены были готовы. Но нам не хватало флага. Я попросил у бабушки кусок зелёной ткани. Я привязал её к палке и водрузил на крепость. Все закричали от радости. Теперь у нас было секретное место.", questions = listOf("Где построили крепость?", "Из чего сделали стены?", "Что попросил мальчик у бабушки?", "Что сделали друзья, когда флаг установили?")),
        ComprehensionStory(id = "1_10", grade = 1, title = "Чистая кисть", text = "Художник рисовал картину. У него было много красок и одна кисть. Он рисовал красивое небо и зелёный лес. Закончив работу, художник положил кисть в воду. Потом он помыл кисть с мылом. Теперь кисть снова чистая и готова к работе. Художник любит, когда его инструменты в порядке.", questions = listOf("Что рисовал художник?", "Что он нарисовал?", "Куда художник положил кисть?", "Каким инструментом он пользуется?")),
        ComprehensionStory(id = "1_11", grade = 1, title = "Короткий карандаш", text = "У Пети был самый обычный карандаш. Петя рисовал им каждый день. Карандаш становился всё короче и короче. Вскоре от него остался маленький огрызок. Папа сказал Пете, что пора выбросить старый карандаш. Но Петя не выбросил его. Он положил карандаш в коробку. Ведь это был его самый верный помощник.", questions = listOf("Что было у Пети?", "Как менялся карандаш?", "Что предложил папа?", "Почему Петя не выбросил карандаш?")),
        ComprehensionStory(id = "1_12", grade = 1, title = "Ключ на ленте", text = "Мама дала Оле ключ от квартиры. Чтобы ключ не потерялся, мама привязала его к ленте. Оля надела ленту с ключом на шею. Теперь ключ всегда был рядом. Оля вернулась из школы, открыла дверь и сняла ленту. Она повесила ключ на гвоздик в прихожей. Мама похвалила Олю за то, что она не потеряла ключ.", questions = listOf("Что мама дала Оле?", "Зачем мама привязала ключ к ленте?", "Куда Оля надела ленту?", "Куда Оля повесила ключ дома?")),
        ComprehensionStory(id = "1_13", grade = 1, title = "Книжка для куклы", text = "У Ани была красивая кукла. Аня очень любила с ней играть. Однажды Аня решила сделать для куклы книжку. Она взяла маленькие листочки бумаги и нарисовала в них картинки. Потом Аня сшила листочки нитками. Получилась маленькая книжка. Кукла была очень рада. Аня усадила её поудобнее и стала читать ей книжку.", questions = listOf("Что Аня решила сделать для куклы?", "Из чего Аня сделала книжку?", "Как Аня соединила листочки?", "Что Аня стала делать после этого?")),
        ComprehensionStory(id = "1_14", grade = 1, title = "За окном автобуса", text = "Я ехал в автобусе и смотрел в окно. За окном мелькали дома и деревья. На улице шёл дождь. Люди бежали под зонтиками. Вдруг я увидел радугу. Она была очень яркая и красивая. Я показал радугу маме. Мама улыбнулась и сказала, что это к хорошей погоде. Скоро дождь закончился, и вышло солнышко.", questions = listOf("Куда смотрел мальчик?", "Какая была погода на улице?", "Что мальчик увидел в окно?", "Что сказала мама?")),
        ComprehensionStory(id = "1_15", grade = 1, title = "Полосатый камешек", text = "На берегу реки Ваня нашёл красивый камешек. Он был гладкий и полосатый. Полоски были белые и серые. Ваня положил камешек в карман. Дома он показал находку маме. Мама сказала, что это очень красивая галька. Ваня поставил камешек на полку. Теперь он всегда напоминает ему о лете.", questions = listOf("Где Ваня нашёл камешек?", "Каким был камешек?", "Куда Ваня положил камешек?", "Куда Ваня поставил камешек дома?")),
        ComprehensionStory(id = "1_16", grade = 1, title = "Билеты в театр", text = "Сегодня мы идём в театр! Мама купила билеты на детский спектакль. Я очень ждал этого дня. В театре мы сдали наши куртки в гардероб. Наши места были в первом ряду. На сцене артисты показывали весёлую сказку. Я громко хлопал в ладоши. После спектакля мы купили мороженое. Это был лучший день!", questions = listOf("Куда шли дети с мамой?", "Куда они сдали куртки?", "Где были их места?", "Что делали артисты на сцене?")),
        ComprehensionStory(id = "1_17", grade = 1, title = "Три цвета", text = "У Кати была коробка с красками. Она достала три цвета: красный, жёлтый и синий. Красным Катя нарисовала яблоко. Жёлтым — солнышко. Синим — тучку. А потом Катя смешала краски. Красный и жёлтый дали оранжевый. А синий и жёлтый — зелёный. Катя нарисовала зелёную травку. Как много цветов можно получить из трёх красок!", questions = listOf("Сколько цветов достала Катя?", "Что она нарисовала красным?", "Какие цвета дали оранжевый цвет?", "Что Катя нарисовала зелёным?")),
        ComprehensionStory(id = "1_18", grade = 1, title = "Тени на стене", text = "Вечером в комнате стало темно. Папа включил настольную лампу. Я поднял руки и увидел на стене тень. Тень была похожа на большого зайца. Я сложил пальцы, и получился волк. Папа тоже стал показывать тени. Мы играли с тенями, пока не пришло время спать. Было очень весело и интересно.", questions = listOf("Когда в комнате стало темно?", "Что я увидел на стене?", "На кого была похожа тень?", "Кто еще играл с тенями?")),
        ComprehensionStory(id = "1_19", grade = 1, title = "Бумажная цепочка", text = "Маша вырезала из бумаги полоски. Она склеила первую полоску в колечко. Потом она продела бумажную полоску через колечко и склеила её. Так у Маши получилась бумажная цепочка. Маша сделала длинную цепочку из разных цветов. Она повесила её на ёлку. Теперь ёлка стала красивой и нарядной. Маша довольна своей работой.", questions = listOf("Что вырезала Маша?", "Что она сделала из первой полоски?", "Куда Маша повесила цепочку?", "Почему Маша довольна?")),
        ComprehensionStory(id = "1_20", grade = 1, title = "Капли на окне", text = "На улице шёл дождь. Я сидел у окна и смотрел на капли. Капли были похожи на маленькие прозрачные шарики. Одна капля побежала вниз и слилась с другой. Получилась большая капля. Я подставил ладошку к стеклу, но капля была снаружи. Я люблю смотреть, как идёт дождь. После дождя воздух становится чистым.", questions = listOf("Какая была погода на улице?", "На что были похожи капли?", "Куда побежала одна капля?", "Почему мальчик любит смотреть на дождь?")),
        ComprehensionStory(id = "1_21", grade = 1, title = "Сапоги у двери", text = "У двери стоят мои сапоги. Они совсем новые и красивые. Вчера мы гуляли по лужам. Мои сапоги промокли. Мама поставила их у батареи сушиться. Сегодня сапоги высохли. Я обул их и снова побежал на улицу. Они не боятся ни дождя, ни грязи. Мои сапоги — самые лучшие в мире.", questions = listOf("Где стоят сапоги?", "Куда ходил мальчик вчера?", "Где мама поставила сапоги?", "Куда мальчик побежал сегодня?")),
        ComprehensionStory(id = "1_22", grade = 1, title = "Тарелка для друзей", text = "Мама купила новую красивую тарелку. На ней были нарисованы синие цветы. Я очень хотел показать её своим друзьям. Я пригласил друзей в гости. Мама положила на тарелку вкусные пирожки. Мы все вместе пили чай. Друзьям очень понравилась новая тарелка. Им понравилось у меня в гостях.", questions = listOf("Что купила мама?", "Что было нарисовано на тарелке?", "Кого пригласил мальчик?", "Что мама положила на тарелку?")),
        ComprehensionStory(id = "1_23", grade = 1, title = "Низкий стол", text = "В детской комнате стоит низкий стол. За ним очень удобно играть в кубики и собирать пазлы. Сегодня мы с братом построили на столе большой город. Там были высокие башни и длинные дороги. Мама позвала нас обедать. Но мы не хотели уходить. Ведь на столе нас ждал целый мир!", questions = listOf("Где стоит низкий стол?", "Что удобно делать за столом?", "Что построили братья на столе?", "Почему дети не хотели уходить обедать?")),
        ComprehensionStory(id = "1_24", grade = 1, title = "Записка на столе", text = "Утром я проснулся и увидел на столе записку. Это мама оставила мне записку. Она написала, что ушла на работу, а завтрак в холодильнике. Ещё мама попросила меня помыть посуду. Я прочитал записку и улыбнулся. Я пошёл на кухню и достал вкусный завтрак. Спасибо маме за заботу и любовь!", questions = listOf("Что увидел мальчик на столе?", "Кто оставил записку?", "Что мама попросила сделать?", "Куда мальчик пошёл после чтения?")),
        ComprehensionStory(id = "1_25", grade = 1, title = "Мяч под скамейкой", text = "Дети играли во дворе в футбол. Ваня сильно ударил по мячу. Мяч закатился под скамейку. Ваня побежал за ним, но там сидел большой пёс. Пёс охранял мяч и громко рычал. Ваня испугался. Тогда его друг Петя принёс кусочек колбасы. Пёс понюхал лакомство и отошёл. Ваня забрал мяч, и игра продолжилась.", questions = listOf("Во что играли дети?", "Куда закатился мяч?", "Кто сидел под скамейкой?", "Как Петя помог другу?")),

        // ==========================================
