        ComprehensionStory(id = "2_1", grade = 2, title = "Один большой зонт", text = "Когда закончились уроки, на улице начался дождь. Оля достала из рюкзака большой жёлтый зонт. У дверей школы стоял её сосед Артём. Свой зонт он оставил дома и ждал, когда дождь станет тише. Оля предложила идти вместе. Дорожка проходила мимо большой лужи, и ребята пошли вдоль забора. Артём нёс папку Оли, чтобы ей было удобнее держать зонт. Дома Оля поставила зонт сушиться. Мама удивилась, что папка осталась сухой. Девочка рассказала, как они помогли друг другу.", questions = listOf("Почему Артём ждал у дверей школы?", "Почему ребята пошли вдоль забора?", "Как Артём помог Оле?", "Что Оля сделала с зонтом дома?")),
        ComprehensionStory(id = "2_2", grade = 2, title = "План двора", text = "Наш двор очень большой и красивый. Но на детской площадке часто бывает грязно. Мы с друзьями решили нарисовать план нашего двора. На большом листе бумаги мы нарисовали качели, песочницу и футбольное поле. Красным карандашом мы отметили места, где нужно поставить новые урны для мусора. Зелёным цветом мы закрасили клумбы, которые хотим посадить весной. Мы показали наш план управляющему домом. Он внимательно посмотрел на рисунок и улыбнулся. Управляющий сказал, что наш план очень полезный. Скоро во дворе появятся новые урны, а мы с друзьями будем следить за чистотой.", questions = listOf("Что решили сделать друзья?", "Что они нарисовали на листе?", "Какой цвет использовали для клумб?", "Что сказал управляющий?")),
        ComprehensionStory(id = "2_3", grade = 2, title = "Свободная скамейка", text = "В солнечный субботний день Аня и её младший брат Костя пошли в городской парк. Они взяли с собой мяч и решили поиграть. Когда ребята устали, они захотели посидеть. В парке было много людей, и почти все скамейки оказались заняты. Наконец Аня заметила одну свободную скамейку в тени дуба. Они с Костей уже собирались сесть на неё, но вдруг увидели пожилую женщину с тяжёлыми сумками. Женщина медленно шла по дорожке и тяжело дышала. Аня сразу же подбежала к ней и предложила присесть. Брат поддержал сестру, и они помогли женщине донести сумки. Женщина поблагодарила ребят и сказала, что они очень воспитанные. Ведь помогать старшим — это очень важно.", questions = listOf("Куда пошли Аня и Костя?", "Почему ребята не смогли сразу сесть на скамейку?", "Кого они увидели на дорожке?", "Как поступили дети?")),
        ComprehensionStory(id = "2_4", grade = 2, title = "Занавес для театра", text = "В нашем классе мы решили сделать настоящий кукольный театр. Ребята принесли разные игрушки и сделали сцену из большой коробки. Но нам не хватало красивого занавеса. Тогда Маша принесла из дома кусок красной ткани. Мы все вместе взялись за дело. Папа одного мальчика помог нам прибить ткань к деревянной палке. Занавес получился ярким и нарядным. Теперь перед началом представления мы торжественно закрываем и открываем сцену. Кукольный театр получился как настоящий!", questions = listOf("Что решили сделать в классе?", "Из чего сделали сцену?", "Что принесла Маша?", "Кто помог прибить ткань?")),
        ComprehensionStory(id = "2_5", grade = 2, title = "Письмо в конверте", text = "Бабушка живёт в другом городе, и мы редко видимся. Вчера я решил написать ей настоящее бумажное письмо. Я взял чистый лист и ручку. Я написал бабушке о том, как учусь в школе, какие оценки получаю и как гуляю с друзьями. Потом я нарисовал для неё солнышко и свой дом. Мама дала мне белый конверт. Я сложил письмо, заклеил конверт и наклеил марку. Сегодня утром мы опустили письмо в почтовый ящик. Бабушка будет очень рада.", questions = listOf("Где живёт бабушка?", "Что мальчик решил написать бабушке?", "Что он нарисовал?", "Куда они опустили письмо?")),
        ComprehensionStory(id = "2_6", grade = 2, title = "Красная варежка", text = "Наступила настоящая зима, и ударили сильные морозы. Мама купила Пете новые тёплые варежки. Они были ярко-красного цвета, и мальчику они очень понравились. В первый же день Петя надел их и побежал кататься с горки. Дети весело лепили снеговика и играли в снежки. В самый разгар игры Петя почувствовал, что одна варежка слетела. Он начал искать её в сугробах, но всё было напрасно. Мальчик расстроился и пошёл домой. По дороге он увидел дворника, который разгребал снег. В руке дворник держал ту самую красную варежку. Он нашёл её на дорожке. Петя обрадовался и поблагодарил дворника.", questions = listOf("Что купила мама Пете?", "Что случилось во время игры?", "Кто нашёл варежку?", "Какое настроение было у Пети в конце?")),
        ComprehensionStory(id = "2_7", grade = 2, title = "Подпись под фотографией", text = "В нашей семье есть большой фотоальбом. В нём много старых чёрно-белых фотографий. Недавно мама достала его с полки и мы начали смотреть снимки. Я увидел фотографию, где мой прадедушка стоит на фоне старого дома. Под снимком была подпись, написанная красивым почерком. Там было написано: «Лето 1950 года». Я очень удивился. Ведь этот снимок был сделан очень давно! Мама рассказала мне интересную историю о моём прадедушке. Теперь я знаю историю своей семьи.", questions = listOf("Что мама достала с полки?", "Кто был на фотографии?", "Что было написано под снимком?", "Что мама рассказала мальчику?")),
        ComprehensionStory(id = "2_8", grade = 2, title = "Лёгкий рюкзак", text = "Завтра мы всем классом идём в поход. Я очень ждал этот день. Вчера вечером я начал собирать свой рюкзак. Сначала я хотел взять с собой много игрушек и книг. Но мама сказала, что в походе рюкзак должен быть лёгким. Тогда я положил в него только самое необходимое: бутылку воды, бутерброды и дождевик. Я убрал тяжёлые вещи. Теперь мой рюкзак очень лёгкий. Завтра я смогу долго идти и не устану.", questions = listOf("Куда шёл класс?", "Что мальчик начал делать вчера?", "Почему рюкзак должен быть лёгким?", "Что мальчик положил в рюкзак?")),
        ComprehensionStory(id = "2_9", grade = 2, title = "Синяя лента", text = "У Алисы были длинные красивые волосы. Каждое утро мама заплетала ей косички. Однажды мама подарила Алисе синюю атласную ленту. Лента была очень гладкой и блестящей. Алиса с радостью вплела её в косу и пошла в школу. В школе все девочки обратили внимание на её причёску. Учительница сказала, что Алиса выглядит очень аккуратно. После школы Алиса побежала во двор. Синяя лента красиво развевалась на ветру. Девочка была очень счастлива.", questions = listOf("Какие волосы были у Алисы?", "Что мама подарила Алисе?", "Куда Алиса вплела ленту?", "Как отреагировали в школе?")),
        ComprehensionStory(id = "2_10", grade = 2, title = "Два бумажных пакета", text = "Мама попросила меня сходить в магазин за хлебом и молоком. Я взял с собой два бумажных пакета, чтобы не покупать пластиковые. В магазине я купил хлеб и положил его в первый пакет. Потом я взял молоко и положил его во второй пакет. По дороге домой я встретил соседскую бабушку. У неё было тяжело в руках. Я предложил помочь ей донести сумки. Бабушка обрадовалась и поблагодарила меня. Я пришёл домой и отдал маме продукты. Мама похвалила меня за помощь.", questions = listOf("За чем мама попросила сходить?", "Зачем мальчик взял два пакета?", "Кого он встретил по дороге?", "За что мама похвалила мальчика?")),
        ComprehensionStory(id = "2_11", grade = 2, title = "Узор в прихожей", text = "В нашей прихожей на полу лежит старый коврик. На нём выткан красивый узор. Там есть большие красные цветы и зелёные листья. Однажды я пролил на него сок и очень испугался. Я думал, что мама будет ругаться. Но мама не рассердилась. Она дала мне щётку и мыло. Мы вместе почистили коврик. Узор снова стал ярким и чистым. Мама сказала, что если что-то испортил, нужно сразу это исправить. Теперь я всегда аккуратно хожу по прихожей.", questions = listOf("Что лежит в прихожей?", "Какой узор на коврике?", "Что мальчик пролил на коврик?", "Что сказала мама?")),
        ComprehensionStory(id = "2_12", grade = 2, title = "Кто сегодня дежурит", text = "Сегодня у нас в классе особенный день. Учительница сказала, что мы будем выбирать дежурных на следующую неделю. Дежурить очень почётно, ведь дежурные должны помогать учителю и поддерживать чистоту. Мы решили выбирать по очереди, чтобы никто не обиделся. На этой неделе очередь дошла до меня и моего друга Артёма. Мы пришли в школу раньше всех и подготовили класс к урокам. Артём протёр доску, а я полил цветы и раздал тетради. На переменах мы следили за порядком и проветривали кабинет. Учительница похвалила нас и сказала, что мы отлично справились. Дежурить оказалось приятно.", questions = listOf("Что сказала учительница в начале дня?", "С кем дежурил мальчик?", "Что делали дежурные на переменах?", "Понравилось ли детям дежурить?")),
        ComprehensionStory(id = "2_13", grade = 2, title = "Ворота для машины", text = "У нашего дедушки есть дача и старенькая машина. Чтобы машина не стояла на улице, папа решил построить для неё ворота. Мы с папой поехали на дачу в выходные. Папа привёз доски и инструменты. Сначала мы выкопали ямы для столбов. Потом мы установили столбы и забетонировали их. Когда бетон высох, папа прибил к столбам ровные доски. Получились красивые и крепкие ворота. Теперь машина будет в безопасности. Я очень гордился тем, что помогал папе строить.", questions = listOf("Что есть у дедушки?", "Что решил построить папа?", "Что они выкопали сначала?", "Почему мальчик гордился?")),
        ComprehensionStory(id = "2_14", grade = 2, title = "Тихий звон", text = "У бабушки на полке стоят старые часы. Они очень большие и деревянные. Каждый час эти часы издают тихий звон. Мне очень нравится слушать этот звук. Он совсем не громкий и никому не мешает. Однажды часы остановились. В доме стало очень тихо и непривычно. Я позвал папу, и он открыл заднюю дверцу часов. Мы вместе подтянули цепочку, и часы снова пошли. Теперь я каждый вечер слушаю их тихий звон перед сном.", questions = listOf("Какие часы стоят у бабушки?", "Какой звук издают часы?", "Что случилось однажды?", "Как папа и мальчик починили часы?")),
        ComprehensionStory(id = "2_15", grade = 2, title = "Корабль на открытке", text = "Бабушка принесла из почтового ящика красивую открытку. На ней был нарисован большой парусный корабль, плывущий по синему морю. Открытка пришла от нашего дедушки, который сейчас работает далеко на севере. Дедушка пишет, что очень скучает по нам и скоро вернётся. Мы поставили открытку на полку, чтобы она стояла на видном месте. Каждый вечер я смотрю на корабль и представляю, как дедушка плывёт к нам на этом корабле. Папа сказал, что корабли на картинках всегда плывут к берегу. Значит, и наш дедушка обязательно приедет. Я очень жду его возвращения.", questions = listOf("Откуда бабушка принесла открытку?", "Что было нарисовано на открытке?", "От кого пришла открытка?", "О чём мальчик думает каждый вечер?")),
        ComprehensionStory(id = "2_16", grade = 2, title = "Шарф для мишки", text = "У младшей сестры есть любимый плюшевый мишка. Он мягкий и очень пушистый. Зимой сестра сказала, что мишке холодно. Она попросила меня связать ему шарф. Я взяла пряжу и спицы. Я вязала шарф ярко-зелёного цвета. Это заняло у меня два вечера. Когда шарф был готов, я повязала его мишке на шею. Сестра была в восторге. Теперь мишка сидит на полке в тёплом шарфе и выглядит очень нарядным.", questions = listOf("Кто есть у младшей сестры?", "Что сестра попросила связать?", "Какого цвета был шарф?", "Как отреагировала сестра?")),
        ComprehensionStory(id = "2_17", grade = 2, title = "Партия после обеда", text = "После обеда мы с папой решили сыграть в шахматы. Это моя самая любимая игра. Папа хорошо играет, но я всегда стараюсь. Мы расставили фигуры на доске. Папа начал игру с центральной пешки. Я подумал и сделал ход конём. Мы играли очень долго. В комнате было тихо. Каждый думал над своим ходом. В итоге партия закончилась вничью. Папа сказал, что я стал играть намного лучше. Я был очень рад.", questions = listOf("Во что играли папа и сын?", "Какая игра любимая?", "С чего папа начал игру?", "Чем закончилась партия?")),
        ComprehensionStory(id = "2_18", grade = 2, title = "Шапка снеговика", text = "В выходные мы с друзьями лепили снеговика. Он получился очень большой. Мы скатали три снежных шара. Вместо глаз мы вставили угольки, а вместо носа — морковку. На голову мы надели ведро. Но ведро было тяжёлым и всё время падало. Тогда Маша принесла из дома старую вязаную шапку. Мы надели шапку на снеговика. Она была ему как раз впору. Теперь наш снеговик стоял красивый и смешной. Никто из ребят не остался равнодушным.", questions = listOf("Что лепили дети?", "Что вставили вместо глаз?", "Почему падало ведро?", "Что принесла Маша?")),
        ComprehensionStory(id = "2_19", grade = 2, title = "Записка на двери", text = "Мы с братом вернулись из школы и увидели на двери записку. Её оставила мама. В записке было написано, что мама ушла в магазин, а ключи она забыла оставить дома. Мама просила нас подождать её на скамейке во дворе. Мы не стали расстраиваться. Мы оставили рюкзаки у соседки и пошли во двор. Там мы играли в песочнице и катались с горки. Через полчаса мама вернулась и открыла дверь. Мы рассказали ей, как весело провели время.", questions = listOf("Где дети нашли записку?", "Кто её оставил?", "Что мама забыла сделать?", "Где дети ждали маму?")),
        ComprehensionStory(id = "2_20", grade = 2, title = "Деталь с облаком", text = "В конструкторе моего брата есть особая деталь. Это маленький синий кубик, на котором нарисовано белое облако. Брат всегда берёт его, когда строит домики. Он говорит, что это «небо». Однажды мы собирали замок, и эта деталь потерялась. Мы искали её по всей комнате. Брат очень расстроился и чуть не заплакал. Но я нашёл кубик под кроватью. Я отдал его брату. Он улыбнулся и сразу поставил деталь на вершину замка. Теперь небо на месте.", questions = listOf("Какая деталь есть в конструкторе?", "Что нарисовано на кубике?", "Что случилось с деталью?", "Где мальчик нашёл деталь?")),
        ComprehensionStory(id = "2_21", grade = 2, title = "Карточки с именами", text = "В начале учебного года учительница раздала нам карточки с именами. Мы должны были положить их на парту. Я написал своё имя красивыми буквами. Оля нарисовала на своей карточке ромашки. А Витя нарисовал самолётик. У всех получилось очень красиво. Учительница сказала, что теперь она быстро запомнит, как нас зовут. Эти карточки стояли у нас на столах целую неделю. Потом мы убрали их в папки. Но я до сих пор храню свою карточку. Она напоминает мне о первом дне в школе.", questions = listOf("Что раздала учительница?", "Что нарисовала Оля?", "Что нарисовал Витя?", "Почему мальчик до сих пор хранит карточку?")),
        ComprehensionStory(id = "2_22", grade = 2, title = "Две одинаковые кошки", text = "У нашей соседки тёти Оли живут две кошки. Они абсолютно одинаковые. Обе серые и пушистые. Зовут их Муся и Дуся. Даже мы долго не могли их различить. Но потом я заметил одну особенность. У Муси на левом ушке есть маленькая белая точка. А у Дуси на хвостике белый кончик. Когда я рассказал об этом тёте Оле, она засмеялась. Оказалось, что я первый заметил это отличие. Теперь я всегда их различаю, и это очень забавно.", questions = listOf("Какие кошки живут у тёти Оли?", "Как их зовут?", "Как мальчик научился их различать?", "Что сказала тётя Оля?")),
        ComprehensionStory(id = "2_23", grade = 2, title = "Место для гостя", text = "Сегодня к нам в гости приезжает бабушка. Мама попросила меня подготовить для неё место. Я взял чистую скатерть и накрыл стол. Потом я принёс из шкафа большую и мягкую подушку. Я положил её на стул рядом с окном. Мама сказала, что бабушка любит смотреть в окно. Ещё я поставил на стол вазу с цветами. Пусть бабушке будет уютно. Наконец раздался звонок в дверь. Я побежал встречать бабушку. Она вошла и улыбнулась, увидев, как я её ждал.", questions = listOf("Кто приезжает в гости?", "Что мальчик накрыл скатертью?", "Куда он положил подушку?", "Что мальчик ещё поставил на стол?")),
        ComprehensionStory(id = "2_24", grade = 2, title = "Чтение по ролям", text = "На уроке литературы мы читали сказку по ролям. Учительница выбрала меня на роль хитрой лисы. Мой друг Петя играл волка, а Маша — зайца. Мы очень старались читать с выражением. Лиса должна была говорить хитрым голосом. Я вспомнил, как лиса говорит в мультфильмах, и попробовал ей подражать. Ребятам в классе очень понравилось. Они даже засмеялись и захлопали в ладоши. Учительница поставила нам хорошие оценки. Читать по ролям оказалось очень увлекательно.", questions = listOf("Что делали на уроке литературы?", "Кого играл мальчик?", "Как он старался говорить?", "Как отреагировали ребята?")),
        ComprehensionStory(id = "2_25", grade = 2, title = "Ракушки в коробке", text = "Прошлым летом наша семья отдыхала на берегу моря. Каждый день я ходил на пляж и собирал красивые ракушки. Мне попадались маленькие и большие, белые и полосатые. Я складывал их в карман и мыл дома от песка. Когда отдых закончился, я сложил все свои сокровища в большую картонную коробку. Дома я поставил её на подоконник. Зимой, когда за окном идёт снег, я открываю коробку и достаю ракушки. Я прикладываю их к уху и слышу шум прибоя. Мне сразу становится тепло и радостно на душе.", questions = listOf("Где отдыхала семья летом?", "Какие ракушки собирал мальчик?", "Куда он сложил сокровища?", "Что мальчик слышит в ракушках?")),

        // ==========================================
        // --- 3 КЛАСС (114-135 слов, 4 вопроса) ---
        // ==========================================
        ComprehensionStory(id = "3_1", grade = 3, title = "Утренний маршрут", text = "Каждое утро Саша ходил в школу одной и той же короткой дорогой. Но сегодня он вышел пораньше и решил пойти через старый парк. В парке было тихо и прохладно. Саша увидел, как рыжая белка ловко прыгает по веткам старого дуба. Чуть дальше, у пруда, важно ходила утка с маленькими жёлтыми утятами. Мальчик засмотрелся на них и даже остановился. Он достал из рюкзака кусочек хлеба и покрошил птицам. Утка громко крякнула, будто поблагодарила его. Саша посмотрел на часы и понял, что чуть не опоздал в школу. Он быстро побежал, но настроение у него было отличное. Этот длинный маршрут оказался намного интереснее короткого.", questions = listOf("Как обычно Саша ходил в школу?", "Кого мальчик увидел в парке?", "Чем Саша угостил утку?", "Почему настроение у Саши было отличное?")),
        ComprehensionStory(id = "3_2", grade = 3, title = "Книжная закладка", text = "Марина очень любила читать книги. Но каждый раз, закрывая книгу, она забывала, на какой странице остановилась. Тогда Марина решила сделать себе закладку. Сначала она хотела взять обычный фантик от конфеты, но потом передумала. Девочка достала плотный картон, ножницы и цветные карандаши. Она вырезала длинную ровную полоску и нарисовала на ней яркие ромашки. В самом уголке Марина аккуратно написала свое имя. Закладка получилась очень красивой и удобной. Теперь, когда Марина закрывает книгу, она всегда кладет её внутрь. Больше она никогда не теряет нужную страницу.", questions = listOf("Что Марина любила делать?", "Из чего она решила сделать закладку?", "Что Марина нарисовала на картоне?", "Как изменилось чтение после появления закладки?")),
        ComprehensionStory(id = "3_3", grade = 3, title = "Мост для игрушек", text = "В дождливый день Паша и Катя строили целый город из деревянных кубиков. Они расставили высокие башни и маленькие домики. Но у них возникла проблема: две части города разделяла «река» из синей ткани. Игрушечным машинкам нужно было как-то перебираться на другую сторону. Катя предложила построить мост. Паша нашел длинную линейку, но она была слишком скользкой. Тогда Катя принесла плотный картон и сложила его пополам. Они аккуратно положили картон через «реку». Мост получился прочным. Теперь машинки могли свободно ездить по своим делам в любую часть города.", questions = listOf("Что строили дети в дождливый день?", "Что разделяло город?", "Почему линейка не подошла для моста?", "Из чего Катя сделала мост?")),
        ComprehensionStory(id = "3_4", grade = 3, title = "Обратная дорога", text = "В выходные мы с папой пошли в лес за грибами. Мы долго бродили по тропинкам и набрали целую корзину лисичек. Незаметно для себя мы зашли очень далеко. Вдруг папа остановился и сказал, что нам пора возвращаться. Я испугался, что мы заблудились, ведь лес был огромным. Но папа улыбнулся и показал на снег, который лежал в тени деревьев. На нём чётко были видны наши следы. Мы пошли по обратной дороге, внимательно глядя под ноги. Следы привели нас прямо к знакомой тропинке. Так мы благополучно вернулись домой.", questions = listOf("Куда пошли папа и ребёнок?", "Что они набрали в лесу?", "Почему мальчик испугался?", "Как им удалось найти дорогу домой?")),
        ComprehensionStory(id = "3_5", grade = 3, title = "Костюм облака", text = "В детском саду готовились к весеннему утреннику. Воспитательница сказала, что все девочки будут снежинками. Но Оле очень хотелось быть белым пушистым облаком. Мама решила помочь дочке. Они взяли много ваты и большой кусок белой ткани. Мама сшила широкий плащ, а Оля приклеила к нему кусочки ваты. На утреннике Оля надела этот костюм и вышла в центр зала. Она кружилась, и вата развевалась, как настоящее облако. Все дети и родители громко хлопали ей. Оля была счастлива, что у неё получился такой необычный наряд.", questions = listOf("Кем должны были быть девочки на утреннике?", "Кем хотела быть Оля?", "Из чего мама и Оля сделали костюм?", "Как отреагировал зал на костюм девочки?")),
        ComprehensionStory(id = "3_6", grade = 3, title = "Первый пас", text = "Никита долго ждал летних каникул, чтобы начать играть в футбол с дворовыми мальчишками. Наконец наступил июнь, и они собрались на стадионе. Никиту поставили на ворота. Он очень волновался, боясь пропустить гол. Вдруг нападающий другой команды сильно ударил по мячу. Никита прыгнул в сторону и поймал мяч! Это был его первый удачный пас. Друзья подбежали и похлопали его по плечу. Никита почувствовал себя настоящим вратарем. После игры он понял, что главное — не бояться и верить в свои силы.", questions = listOf("Чего ждал Никита?", "На какую позицию его поставили?", "Почему Никита волновался?", "Что понял мальчик после игры?")),
        ComprehensionStory(id = "3_7", grade = 3, title = "До первого ростка", text = "На уроке труда нам дали задание посадить семена. Я взял маленький горшочек и насыпал в него земли. Мама дала мне семечко огурца. Я посадил его и полил водой. Каждый день я проверял горшочек, но земля оставалась чёрной и пустой. Я начал думать, что семечко погибло. Но учитель сказал, что нужно набраться терпения. Через неделю я прибежал в класс и увидел крошечный зелёный росток! Он пробился сквозь землю к свету. Я был так рад, что даже закричал. Теперь я знаю, что природа требует времени.", questions = listOf("Что дали на уроке труда?", "Какое семечко дала мама?", "Почему мальчик переживал?", "Что случилось через неделю?")),
        ComprehensionStory(id = "3_8", grade = 3, title = "Ход для младшего", text = "Мы с братом Пашей очень любим играть в шашки. Обычно мы всегда играем честно, и Паша часто выигрывает. Но в этот раз он долго думал над каждым ходом и всё равно проигрывал. Я видел, как сильно он расстроился. Тогда я решил сделать ему небольшой подарок. Я предложил ему сделать последний ход за меня. Паша удивился, но согласился. Он сделал ход, и моя шашка оказалась в ловушке. Теперь уже он выиграл, а я проиграл. Паша улыбнулся. Мне было приятнее видеть его радость, чем выиграть самому.", questions = listOf("Во что любили играть братья?", "Как Паша реагировал на проигрыш?", "Что предложил автор рассказа брату?", "Почему автору было приятно проиграть?")),
        ComprehensionStory(id = "3_9", grade = 3, title = "Полоска для рамки", text = "Для урока рисования нам задали нарисовать пейзаж. Я нарисовал красивый закат над рекой. Но лист бумаги выглядел слишком простым. Мне захотелось сделать для рисунка рамку. Я взял цветной картон и вырезал из него длинные полоски. Сначала я приклеил две полоски сверху и снизу. Потом приклеил две полоски по бокам. Получилась ровная и аккуратная рамка. Теперь мой рисунок висел на стене как настоящая картина. Учительница похвалила меня за аккуратность и творческий подход.", questions = listOf("Что задали нарисовать на уроке?", "Что нарисовал мальчик?", "Из чего он сделал рамку?", "За что похвалила учительница?")),
        ComprehensionStory(id = "3_10", grade = 3, title = "Место для рассказа", text = "Нам в классе задали написать короткий рассказ о лете. Я очень долго не мог начать, потому что в комнате было шумно и мне мешали. Тогда я взял блокнот и ручку и вышел на балкон. Там было тихо, дул свежий ветер. Я сел на маленький стульчик и начал писать. Слова сами складывались в предложения. Я написал про то, как мы с дедушкой ловили рыбу на озере. Когда я вернулся в комнату, рассказ уже был готов. Иногда для хорошей работы нужно найти подходящее место.", questions = listOf("Что задали написать в классе?", "Почему мальчик не мог начать?", "Куда он вышел писать?", "О чём был его рассказ?")),
        ComprehensionStory(id = "3_11", grade = 3, title = "Бабушкина тетрадь", text = "На чердаке я нашёл старую картонную коробку. В ней лежала потрёпанная тетрадь с пожелтевшими страницами. Я открыл её и увидел красивый почерк. Оказалось, что это тетрадь моей бабушки, когда она училась в третьем классе. Бабушка писала там разные стихи и рассказы. Я прочитал один рассказ про смелого котёнка. Мне очень понравилось, как бабушка описывала природу. Я показал находку бабушке, и она улыбнулась. Вечером она прочитала мне ещё несколько своих историй из этой тетради.", questions = listOf("Что мальчик нашёл на чердаке?", "Кому принадлежала тетрадь?", "Что бабушка писала в тетради?", "Что она сделала вечером?")),
        ComprehensionStory(id = "3_12", grade = 3, title = "Не сразу весело", text = "В школе готовили концерт к 8 марта. Наша группа должна была танцевать. Я очень боялся сцены и хотел отказаться. Но мама сказала, что нужно попробовать. Мы репетировали каждый день после уроков. Сначала я путался в движениях и всё время сбивался с ритма. Девочки из группы поддерживали меня и помогали. Постепенно я выучил танец. На концерте я вышел на сцену и станцевал без единой ошибки. Зрители громко хлопали. Тогда я понял, что не надо бояться, если рядом есть друзья.", questions = listOf("К какому празднику готовили концерт?", "Чего боялся мальчик?", "Как девочки помогали мальчику?", "Что он понял после концерта?")),
        ComprehensionStory(id = "3_13", grade = 3, title = "Конверт для ответа", text = "Мы с классом участвовали в конкурсе рисунков. Учительница сказала, что результаты пришлют нам почтой. Мы долго ждали ответа. Каждое утро я заглядывал в почтовый ящик. И вот однажды я увидел большой белый конверт! Внутри лежала грамота за первое место и приглашение на награждение. Но самое главное — там был ещё один пустой конверт для моего ответа. Я должен был подтвердить, что приду на праздник. Я аккуратно заполнил бланк, запечатал его в этот конверт и опустил в ящик. Теперь я с нетерпением жду церемонии награждения.", questions = listOf("В каком конкурсе участвовали дети?", "Что пришло в белом конверте?", "Что нужно было сделать с пустым конвертом?", "Куда мальчик опустил ответ?")),
        ComprehensionStory(id = "3_14", grade = 3, title = "Стол у окна", text = "В нашей квартире на кухне стоит большой деревянный стол. Он расположен прямо у окна. Я очень люблю сидеть за этим столом. Утром здесь светло и солнечно, а зимой можно смотреть, как падает пушистый снег. Вчера я делал за этим столом уроки. Было так уютно и спокойно, что я не заметил, как быстро сделал математику. Мама поставила рядом со мной кружку горячего какао. Этот стол — самое лучшее место в доме. Здесь всегда собирается вся наша семья обедать и пить чай.", questions = listOf("Какой стол стоит на кухне?", "Где он расположен?", "Что мальчик делал за столом вчера?", "Что поставила рядом мама?")),
        ComprehensionStory(id = "3_15", grade = 3, title = "Три дела сразу", text = "По воскресеньям я всегда помогаю маме по дому. Вчера у меня был целый список заданий: полить цветы, убрать игрушки и вытереть пыль. Я решил сделать всё сразу, чтобы быстрее пойти гулять. Я взял тряпку, лейку и начал бегать из комнаты в комнату. Из-за этой спешки я пролил воду на пол и рассыпал игрушки. Мама сказала, что делать три дела сразу — значит, ни одного не сделать хорошо. Я вздохнул, извинился и взялся за работу по порядку. Когда всё было сделано, мама отпустила меня гулять с чистой совестью.", questions = listOf("Что мальчик делал по воскресеньям?", "Какие три дела были у него в списке?", "Что случилось из-за спешки?", "Что сказала мама?")),
        ComprehensionStory(id = "3_16", grade = 3, title = "Время для гостей", text = "В прошлую субботу к нам приехали родственники из другого города. Мама предупредила меня, что у нас будет мало времени на подготовку. Мы быстро убрали в квартире и накрыли на стол. Я помог разложить приборы и расставить стулья. Когда гости приехали, мы пили чай с большим яблочным пирогом. Дядя рассказывал смешные истории, а тётя показывала фотографии. Мы так заговорились, что не заметили, как наступил вечер. Провожая гостей, я понял, что время с близкими пролетает незаметно. Нужно ценить такие тёплые встречи.", questions = listOf("Кто приехал в субботу?", "Что мама поручила мальчику?", "Что ели гости?", "Что понял мальчик, провожая гостей?")),
        ComprehensionStory(id = "3_17", grade = 3, title = "Улица на столе", text = "Мой папа работает архитектором. Иногда он приносит работу домой. Вчера он раскатал на нашем большом столе огромный лист ватмана. Я заглянул и увидел нарисованную улицу с домами, машинами и деревьями. Папа сказал, что это проект новой улицы в нашем городе. Я помогал папе раскрашивать деревья зелёным карандашом. Было очень интересно смотреть, как рождается новая улица прямо у нас на столе. Когда проект будет готов, его построят, и по этой улице будут гулять люди. Я очень горжусь своим папой.", questions = listOf("Кем работает папа?", "Что папа раскатал на столе?", "Что мальчик помогал раскрашивать?", "Чем мальчик гордится?")),
        ComprehensionStory(id = "3_18", grade = 3, title = "Подпись к рисунку", text = "На уроках рисования мы часто рисуем на свободную тему. Вчера я нарисовал дремучий лес и избушку на курьих ножках. Учительница похвалила мой рисунок и предложила повесить его на выставку. Но она сказала, что к рисунку обязательно нужна подпись. Я задумался, что же написать. Можно было написать просто «Лес». Но мне хотелось придумать что-то интересное. Тогда я написал: «Тайна старой избушки». Учительнице очень понравилась моя подпись. Теперь мой рисунок висит в школьном коридоре.", questions = listOf("Что мальчик нарисовал на уроке?", "Куда учительница предложила повесить рисунок?", "Что обязательно нужно к рисунку?", "Как мальчик подписал свою работу?")),
        ComprehensionStory(id = "3_19", grade = 3, title = "Чьи шаги длиннее", text = "Мы с сестрой Настей шли по свежему снегу. Настя шла впереди и оставляла маленькие следы. Я шел сзади, и мои следы были большими. Настя обернулась и спросила, почему у нас такие разные следы. Я объяснил, что у меня нога больше, поэтому и шаг длиннее. Тогда мы решили проверить, кто быстрее дойдет до забора. Я сделал три шага, а Настя — целых пять. Мы посмеялись над этим. Оказывается, длинные шаги помогают быстрее добраться до цели. Но зато с маленькими шагами можно рассмотреть больше интересного вокруг.", questions = listOf("Куда шли брат и сестра?", "Чьи следы были больше?", "Почему у них были разные шаги?", "Кто быстрее дошел до забора?")),
        ComprehensionStory(id = "3_20", grade = 3, title = "Подарок для тёти", text = "У моей тёти скоро день рождения. Мы с мамой долго думали, что ей подарить. В магазине было много красивых вещей, но нам хотелось выбрать что-то особенное. Я вспомнил, что тётя очень любит пить чай и у неё нет красивой салфетки под горячее. Тогда мы купили кусок льняной ткани. Дома я вырезал сердечко и вышил на нём красивые цветы. Получилась замечательная подставка для чашки. Тётя была очень рада, когда открыла мой подарок. Она сказала, что это лучший подарок, потому что он сделан с любовью.", questions = listOf("К какому празднику готовились мама и ребёнок?", "Что любит пить тётя?", "Что они решили подарить?", "Почему тётя назвала подарок лучшим?")),
        ComprehensionStory(id = "3_21", grade = 3, title = "Продолжение сказки", text = "Бабушка часто читает мне на ночь сказки. Вчера она прочитала мне про Красную Шапочку. Но она дочитала только до того места, где волк стучится в дверь. И тут бабушка остановилась и сказала, что устала. Я попросил её дочитать, но она предложила мне самому придумать конец. Я долго лежал в темноте и думал. В моей сказке мимо проходил лесник с собакой, и они спасли бабушку. Утром я рассказал бабушке своё продолжение. Ей так понравилось, что она записала его в специальную тетрадь.", questions = listOf("Что бабушка читала внуку?", "На каком месте она остановилась?", "Что бабушка предложила мальчику?", "Кто спас бабушку в его версии сказки?")),
        ComprehensionStory(id = "3_22", grade = 3, title = "Жребий для команды", text = "В классе мы играли в игру, нужно было разделиться на две команды. Капитанами выбрали Витю и Сашу. Они начали набирать игроков. Я очень хотел попасть в команду к Вите, потому что он всегда придумывает интересные тактики. Но когда до меня дошла очередь, Витя выбрал другого мальчика. Я расстроился и попал в команду Саши. Игра была очень захватывающей. Я старался изо всех сил и в конце концов принес своей команде победное очко. Мы выиграли! Тогда я понял, что неважно, с кем ты в команде, важно, как ты играешь.", questions = listOf("На что делились в классе?", "Кого выбрали капитанами?", "К кому хотел попасть мальчик?", "Кто в итоге выиграл?")),
        ComprehensionStory(id = "3_23", grade = 3, title = "Окошки календаря", text = "В канун Нового года мама подарила мне необычный календарь. Он был сделан в виде домика с окошками. В каждом окошке лежал маленький сюрприз. Мама сказала, что открывать нужно по одному окошку в день. Я очень ждал первого декабря. Утром я открыл первое окошко и нашел там красивую наклейку. В следующие дни мне попадались конфеты и маленькие игрушки. Это было так интересно! Каждое утро я бежал к календарю. Так ожидание праздника стало настоящим приключением. А в последнем окошке меня ждал билет в кино.", questions = listOf("Что мама подарила на Новый год?", "Что лежало внутри календаря?", "Как нужно было открывать окошки?", "Что было в последнем окошке?")),
        ComprehensionStory(id = "3_24", grade = 3, title = "Вывеска для кружка", text = "В нашей школе открылся новый кружок робототехники. Учитель попросил нас придумать и нарисовать для него красивую вывеску. Мы с друзьями сразу взялись за дело. Мы решили нарисовать большого робота с лампочками вместо глаз. Я взял большой лист бумаги и краски. Пока я рисовал, ребята подсказывали мне цвета. Получился очень яркий и забавный робот. Учитель повесил нашу вывеску прямо над дверью кабинета. Теперь все ребята в школе знают, где находится кружок. Нашу вывеску даже сфотографировали для школьной газеты.", questions = listOf("Какой кружок открылся в школе?", "Что попросил нарисовать учитель?", "Что мальчик нарисовал вместо глаз робота?", "Куда повесили вывеску?")),
        ComprehensionStory(id = "3_25", grade = 3, title = "Две похожие тетради", text = "Мы с братом пошли в магазин за школьными принадлежностями. Я выбрал себе тетрадь в клеточку с красивым космическим кораблём на обложке. Брат долго искал и купил такую же. Дома мы положили их на стол. Они были абсолютно одинаковыми. Я испугался, что мы перепутаем их и будем делать уроки в чужой тетради. Тогда я взял красную ручку и нарисовал на своей тетради маленькую звёздочку. Теперь мою тетрадь ни с чьей не перепутаешь. А брат нарисовал на своей зелёный листик.", questions = listOf("Куда пошли братья?", "Какую тетрадь купил мальчик?", "Почему мальчик испугался?", "Что он нарисовал на своей тетради?")),

        // ==========================================
        // --- 4 КЛАСС (154-175 слов, 5 вопросов) ---
        // ==========================================
        ComprehensionStory(id = "4_1", grade = 4, title = "Чья идея лучше", text = "В нашей школе проходил конкурс на лучший проект по благоустройству парка. Мы с друзьями решили участвовать. Сразу начались споры. Петя предложил построить большой фонтан, чтобы было красиво. Маша сказала, что лучше сделать спортивную площадку, чтобы можно было играть. У всех были разные, но очень хорошие идеи. Тогда я предложил объединить всё в один план. Мы нарисовали парк, в центре которого стоял фонтан. Рядом мы разместили площадку с тренажерами. А вокруг посадили много деревьев и сделали удобные скамейки. Мы вместе защитили этот проект перед жюри. Нам дали первое место, потому что мы смогли объединить усилия и выбрать лучшее из каждой идеи.", questions = listOf("В каком конкурсе участвовали друзья?", "Что предложил Петя?", "Что предложила Маша?", "Как друзьям удалось выиграть?", "Почему жюри дало им первое место?")),
        ComprehensionStory(id = "4_2", grade = 4, title = "Два стакана", text = "Бабушка принесла с рынка два красивых стакана. Один был с синими узорами, а другой — с красными. Мне и моему брату нужно было их разделить. Мы сразу начали спорить, кому какой достанется. Каждому хотелось получить стакан с синими узорами. Бабушка смотрела на нас и улыбалась. Тогда она сказала, что отдаст стаканы тому, кто предложит лучший способ их поделить. Я подумал и сказал, что мы можем просто поменяться через неделю. Брат согласился. Бабушка похвалила нас за то, что мы нашли решение без ссоры. В итоге я взял синий стакан, а через неделю мы поменялись. Оказалось, что красный стакан тоже очень красивый.", questions = listOf("Что принесла бабушка?", "Почему братья начали спорить?", "Какое условие поставила бабушка?", "Что предложил мальчик для решения спора?", "Как в итоге поступили братья?")),
        ComprehensionStory(id = "4_3", grade = 4, title = "Проверенная новость", text = "Однажды на перемене мой друг Дима рассказал нам удивительную новость. Он сказал, что в соседнем дворе видел настоящего крокодила, который гулял по траве. Мы все очень удивились и сначала поверили ему. Но потом я задумался. Откуда в нашем городе может взяться крокодил? Я предложил Диме сходить в соседний двор и проверить. Когда мы пришли, то увидели не крокодила, а большого зелёного игуану, которую выгуливала соседка. Дима ошибся, потому что испугался и не рассмотрел. Мы посмеялись, но я объяснил ребятам, что любую новость нужно проверять, прежде чем рассказывать её другим.", questions = listOf("Что рассказал Дима на перемене?", "Почему ребята сначала поверили ему?", "Что мальчик предложил сделать?", "Кого они увидели на самом деле?", "Какой вывод сделали друзья?")),
        ComprehensionStory(id = "4_4", grade = 4, title = "Пауза на сцене", text = "Наш класс готовил спектакль по сказке. Мне досталась главная роль — роль храброго рыцаря. Я выучил все слова и очень хорошо репетировал. Но на самом выступлении, когда я вышел на сцену и увидел полный зал зрителей, я вдруг всё забыл. В зале стало тихо, все смотрели на меня. Я стоял и не мог выговорить ни слова. Мне хотелось убежать за кулисы. Но тут я увидел, как наш учитель музыки улыбнулся мне из первого ряда. Я сделал глубокий вдох и вспомнил первую строчку. Дальше слова полились сами собой. Я сыграл свою роль до конца, и зал взорвался аплодисментами. Главное — не сдаваться, даже если что-то пошло не так.", questions = listOf("Какую роль получил мальчик?", "Что случилось на самом выступлении?", "Что почувствовал мальчик в этот момент?", "Кто помог ему справиться?", "Чем закончилось выступление?")),
        ComprehensionStory(id = "4_5", grade = 4, title = "Нижняя полка", text = "В поезде дальнего следования мы с родителями ехали на море. Мне досталась верхняя боковая полка. Но я очень боялся спать на высоте и попросил родителей поменяться со мной. Мама сказала, что нижняя полка занята пожилым мужчиной. Я расстроился. Вдруг этот мужчина услышал наш разговор и предложил мне свою нижнюю полку. Я удивился и спросил, почему он так поступает. Он ответил, что ему на верхней полке даже удобнее, потому что там можно открыть окно и дышать свежим воздухом. Я поблагодарил его и лёг спать. Утром я понял, что этот человек просто был добрым и не хотел, чтобы я переживал.", questions = listOf("Куда ехала семья на поезде?", "Какая полка досталась мальчику?", "Почему мальчик не хотел спать наверху?", "Что предложил пожилой мужчина?", "Почему мужчина сказал, что наверху даже удобнее?")),
        ComprehensionStory(id = "4_6", grade = 4, title = "После поворота", text = "Мы с папой ехали на машине по незнакомой лесной дороге. Навигатор показывал, что нужно ехать прямо. Вдруг мы увидели знак, который указывал поворот налево. Папа сказал, что навигатор иногда ошибается, и повернул. Мы ехали по узкой дороге, вокруг были только деревья. Я начал переживать, что мы заблудились. Но вдруг лес расступился, и мы увидели небольшое озеро невероятной красоты. Вода в нём была прозрачной, как стекло. Мы остановились, чтобы сделать фотографии. Папа сказал, что иногда нужно отступать от привычного маршрута, чтобы увидеть что-то по-настоящему удивительное.", questions = listOf("Куда ехали папа и ребёнок?", "Что показывал навигатор?", "Что предложил знак на дороге?", "Почему мальчик начал переживать?", "Что они увидели после поворота?")),
        ComprehensionStory(id = "4_7", grade = 4, title = "Мера для теста", text = "В выходные мы с мамой решили испечь пирог. Мама достала поваренную книгу и нашла рецепт. Там было написано, что нужно взять двести граммов муки. Но у нас не было кухонных весов. Мама начала переживать, что пирог не получится. Тогда я вспомнил, что в магазине муку продают в пачках по одному килограмму. Я предложил отмерить муку с помощью обычного стакана. Мы узнали в интернете, что в одном стакане примерно сто шестьдесят граммов муки. Я насыпал полтора стакана. Пирог получился просто отличным! Мы пили чай и смеялись, что я стал настоящим помощником на кухне.", questions = listOf("Что решили испечь мама и ребёнок?", "Что нужно было взять по рецепту?", "Почему мама начала переживать?", "Как они решили отмерить муку?", "Каким получился пирог?")),
        ComprehensionStory(id = "4_8", grade = 4, title = "Уголок неба", text = "Моя бабушка живёт в деревне. У неё есть небольшой сад, где растёт много цветов. Но бабушка больше всего любит синие цветы, которые называются незабудки. Она говорит, что они похожи на маленький кусочек неба. Однажды я приехал к ней в гости и увидел, что клумба с незабудками заросла сорняками. Бабушка болела и не могла за ней ухаживать. Тогда я решил помочь. Я взял тяпку и аккуратно вырвал всю траву вокруг цветов. Потом я полил их водой из лейки. Когда бабушка вышла в сад, она была очень удивлена. Её любимый уголок неба снова засиял яркими красками.", questions = listOf("Где живёт бабушка?", "Какие цветы она любит больше всего?", "С чем бабушка сравнивала незабудки?", "Почему клумба заросла сорняками?", "Как внук помог бабушке?")),
        ComprehensionStory(id = "4_9", grade = 4, title = "Окно напротив", text = "В нашем дворе есть высокий дом. Я часто смотрю в окно и наблюдаю за тем, что происходит вокруг. Однажды я заметил, что в окне напротив каждый вечер зажигается свет. Я начал придумывать, кто там живёт. Мне казалось, что там живёт старый художник, который пишет картины по ночам. Или, может быть, учёный, который изобретает что-то важное. Однажды я встретил соседа из этого подъезда и спросил, кто живёт в той квартире. Оказалось, там живёт обычная девушка-студентка, которая по вечерам делает уроки. Мои фантазии разбились, но мне стало даже интереснее. Ведь в каждом окне кипит своя жизнь.", questions = listOf("Куда часто смотрел мальчик?", "Что он замечал в окне напротив?", "Какие фантазии придумывал мальчик?", "Кто жил в той квартире на самом деле?", "Как изменилось отношение мальчика к этому окну?")),
        ComprehensionStory(id = "4_10", grade = 4, title = "Забытый конь", text = "На чердаке у дедушки я нашел старую деревянную лошадку. Она была покрыта пылью, и у нее не хватало одного колеса. Я показал находку дедушке. Он взял лошадку в руки и улыбнулся. Дедушка рассказал, что это была его любимая игрушка в детстве. Он играл с ней каждый день. Но однажды колесо сломалось, и лошадку убрали на чердак. Мне стало жалко лошадку, и я решил её починить. Я нашел в ящике подходящее деревянное колесико и прибил его гвоздиками. Потом мы с дедушкой покрыли лошадку лаком. Теперь она стоит на полке в моей комнате как настоящая реликвия.", questions = listOf("Что мальчик нашел на чердаке?", "Чего не хватало у лошадки?", "Чьей игрушкой была эта лошадка?", "Почему игрушку убрали на чердак?", "Как мальчик починил лошадку?")),
        ComprehensionStory(id = "4_11", grade = 4, title = "Обычный конверт", text = "В наш почтовый ящик часто бросают рекламные газеты, но в этот раз среди них лежал обычный белый конверт. На нем не было марки, а адрес был написан от руки. Мы с папой очень удивились, ведь в наше время бумажные письма получают редко. Я вскрыл конверт. Внутри оказался старый фотоснимок и небольшое письмо от моего двоюродного дедушки, который живет далеко в Сибири. Он писал, что нашел этот снимок в старом альбоме и решил отправить нам. На фотографии был мой папа в детстве. Он стоял на фоне старой деревянной беседки в нашем парке, держа в руках большого плюшевого медведя. Папа очень удивился, увидев снимок. Он сказал, что совсем забыл про этого медведя, а беседку давно снесли. Мы поставили фотографию в рамку и повесили на стену. Это простое письмо подарило нам много тёплых воспоминаний.", questions = listOf("Что лежало в почтовом ящике?", "Почему папа и мальчик удивились?", "От кого пришло письмо?", "Что было на старом фотоснимке?", "Что сделали с фотографией?")),
        ComprehensionStory(id = "4_12", grade = 4, title = "Последний ответ", text = "На уроке математики учительница написала на доске сложную задачу. Она сказала, что решит её только тот, кто первым поднимет руку. Весь класс склонился над тетрадями. Я тоже начал решать. Задача была запутанной, с множеством действий. Я почти сдался, но потом заметил одну маленькую подсказку в условии. Я быстро досчитал до конца и понял, что нашел правильный ответ. Я поднял руку. Учительница вызвала меня к доске. Я написал решение и назвал ответ. В классе стало тихо. Учительница улыбнулась и сказала, что я решил задачу самым необычным и коротким способом. Оказалось, что я единственный, кто додумался до этого. Мне было очень приятно.", questions = listOf("Что написала учительница на доске?", "Кто должен был решить задачу?", "Почему мальчик почти сдался?", "Как он нашел решение?", "Что сказала учительница?")),
        ComprehensionStory(id = "4_13", grade = 4, title = "За краем фотографии", text = "Я очень люблю рассматривать старые фотографии в бабушкином альбоме. Особенно мне нравится один снимок, где бабушка и дедушка сидят на берегу озера. Они молодые и веселые, а на заднем плане видна старая лодка. Однажды я спросил бабушку, что было за краем этой фотографии. Бабушка задумалась, а потом рассмеялась. Она рассказала, что в тот день они с дедушкой отправились на пикник, но забыли дома всю еду. Им пришлось ловить рыбу голыми руками и печь картошку в костре. На фото они выглядят такими счастливыми, потому что только что пережили это маленькое приключение. Оказывается, за краем любой фотографии скрывается целая история, о которой мы можем узнать, если просто спросим.", questions = listOf("Чей альбом любит рассматривать мальчик?", "Кто нарисован на фотографии?", "Что бабушка рассказала про тот день?", "Почему они выглядели счастливыми на фото?", "Какой вывод сделал мальчик?")),
        ComprehensionStory(id = "4_14", grade = 4, title = "Широкая миска", text = "У нашей собаки по кличке Джесси есть своя посуда. Для воды у неё стоит широкая металлическая миска. Однажды мы заметили, что Джесси очень неудобно пить из неё. Ей приходилось сильно вытягивать шею, и из-за этого брызги летели во все стороны. Я предложил поставить миску на небольшую деревянную подставку. Папа помог мне сколотить маленький устойчивый пьедестал. Мы поставили миску наверх. Джесси сначала обнюхала новую конструкцию, а потом начала пить. Теперь ей было гораздо удобнее, и она больше не разливала воду вокруг. Оказалось, что даже такое простое приспособление может сделать жизнь питомца комфортнее.", questions = listOf("Как зовут собаку?", "В чём неудобство широкой миски?", "Что предложил мальчик?", "Кто помог сделать подставку?", "Как изменилось поведение собаки?")),
        ComprehensionStory(id = "4_15", grade = 4, title = "Голос в коробке", text = "На день рождения мне подарили музыкальную шкатулку. Она была деревянная, украшенная красивой резьбой. Когда я открывал её, оттуда раздавалась тихая, приятная мелодия. Мне очень нравилось слушать этот голос в коробке. Однажды шкатулка упала со стола и замолчала. Я очень расстроился и хотел выбросить её. Но папа сказал, что мы попробуем её починить. Мы открыли заднюю крышку и увидели крошечный механизм. Оказалось, что просто погнулась одна пружинка. Папа аккуратно поправил её. Мы закрыли шкатулку, и она снова заиграла! Оказывается, не всегда нужно спешить выбрасывать сломанную вещь. Иногда стоит заглянуть внутрь и понять, как она устроена.", questions = listOf("Что подарили мальчику на день рождения?", "Что случилось со шкатулкой?", "Что они увидели внутри?", "Как папа починил шкатулку?", "Какой вывод сделал мальчик?")),
        ComprehensionStory(id = "4_16", grade = 4, title = "Правило для всех", text = "В нашем классе есть правило: перед уходом домой мы должны оставлять парты чистыми. Но некоторые ребята часто забывали об этом. Однажды мы с подругой решили напомнить всем о правиле. Мы не стали ругаться или жаловаться учителю. Мы взяли цветной картон и нарисовали красивый плакат. На нем мы написали крупными буквами: «Оставь парту чистой — помоги уборщице!». Мы повесили плакат над доской. На следующий день все парты были убраны. Ребята сказали, что плакат им очень понравился, и теперь они не забывают правило. Оказалось, что вежливое напоминание работает лучше, чем строгие замечания.", questions = listOf("Какое правило было в классе?", "Почему ребята его забывали?", "Что решили сделать девочки?", "Что было написано на плакате?", "Почему плакат подействовал на ребят?")),
        ComprehensionStory(id = "4_17", grade = 4, title = "Стрелка у двери", text = "В нашем подъезде однажды сломалась кнопка на лифте. Лифт работал, но люди не понимали, как его вызвать. Мы с папой купили маленькую самоклеящуюся стрелку. Папа приклеил её рядом с дверью лифта, указывая прямо на кнопку. Теперь любой житель, даже тот, кто впервые приехал в наш дом, сразу понимал, куда нажимать. Соседи заметили нашу стрелку и очень удивились такой заботе. Оказалось, что маленькая стрелка, наклеенная с умом, может решить проблему всего подъезда.", questions = listOf("Что сломалось в подъезде?", "Что решили сделать папа и сын?", "Куда приклеили стрелку?", "Как отреагировали соседи?", "Какую пользу принесла стрелка?")),
        ComprehensionStory(id = "4_18", grade = 4, title = "Карман для мелочи", text = "У моей школьной сумки порвался внутренний карман, куда я всегда складывал разные мелочи: ластики, точилки и монетки. Из-за этого я постоянно терял свои вещи на дне сумки. Мама предложила не выбрасывать сумку, а пришить новый карман. Она достала кусок плотной ткани. Я сам выбрал яркую оранжевую ткань, чтобы карман было хорошо видно. Мама показала мне, как правильно держать иголку и делать ровные стежки. Мы вместе пришили новый карман. Теперь все мои мелочи лежат на своих местах, и я их больше не теряю.", questions = listOf("Что порвалось в сумке?", "Почему мальчик терял вещи?", "Из чего мама предложила сделать карман?", "Какую ткань выбрал мальчик?", "Что мальчик научился делать вместе с мамой?")),
        ComprehensionStory(id = "4_19", grade = 4, title = "Место для чтения", text = "Я очень люблю читать, но в нашей комнате не было специального места для этого. Я читал за письменным столом, на кровати или на полу, и это было не очень удобно. Однажды я увидел в магазине красивое старое кресло. Оно было немного потрепанное, но очень уютное. Мы с папой привезли его домой и поставили в углу у окна. Я принес туда настольную лампу и небольшой пуф для ног. Теперь у меня есть свой собственный уголок для чтения. Когда я сажусь в это кресло, я полностью погружаюсь в мир книг. Это место стало моим самым любимым в доме.", questions = listOf("Что любил делать мальчик?", "Где он обычно читал?", "Что он увидел в магазине?", "Куда поставили кресло?", "Каким стало новое место для чтения?")),
        ComprehensionStory(id = "4_20", grade = 4, title = "Тихий час для задачи", text = "В конце дня у нас в классе всегда бывает сложная задача по математике. Иногда в классе так шумно, что невозможно сосредоточиться. Учительница заметила, что многие ребята не справляются с задачей. И тогда она предложила ввести «тихий час для задачи». Это значит, что на десять минут весь класс замирает, мы даже не поднимаем глаз от тетрадей. Сначала мы думали, что это будет скучно. Но оказалось, что в полной тишине наши мысли работают гораздо лучше. Я решил задачу за пять минут. Учительница сказала, что тишина — это тоже инструмент для учебы. Теперь мы всегда так делаем.", questions = listOf("Какая задача была в конце дня?", "Почему ученикам было трудно?", "Что предложила учительница?", "Что значит «тихий час для задачи»?", "Помогло ли это ребятам?")),
        ComprehensionStory(id = "4_21", grade = 4, title = "Две стороны плаща", text = "У моей мамы есть красивый старый плащ, у которого две стороны. Одна сторона черная, а другая — ярко-красная. Мама говорит, что он очень удобный. В дождливую погоду она носит его черной стороной наружу, чтобы грязь не была видна. А когда она идет гулять со мной в парк, она надевает его красной стороной. Мне очень нравится этот плащ. Однажды я спросил маму, почему она не купит себе новый. Она улыбнулась и сказала, что этот плащ знает много наших секретов. Он хранит тепло ее рук, и у него две стороны, как и у любой истории.", questions = listOf("Какой плащ есть у мамы?", "Какого цвета стороны плаща?", "Как мама носит плащ в дождливую погоду?", "Почему она надевает его красной стороной в парк?", "Почему мама не покупает новый плащ?")),
        ComprehensionStory(id = "4_22", grade = 4, title = "Билет без поездки", text = "Однажды, разбирая старый ящик в гараже, мы с дедушкой нашли маленький картонный билет. На нем было написано «Билет на поезд. 1985 год». Дедушка долго рассматривал его, а потом улыбнулся. Он рассказал, что этот билет был с поездки к бабушке, когда они только познакомились. Дедушка ехал через всю страну, чтобы встретить бабушку на вокзале. Он сказал, что всю дорогу волновался и держал этот билет в кармане как талисман. Поезд опоздал на два часа, но бабушка дождалась его. Дедушка не выбросил этот билет, потому что он напоминает ему о самом важном путешествии в его жизни.", questions = listOf("Что нашли дедушка и внук в гараже?", "Что было написано на билете?", "Куда ехал дедушка?", "Почему он держал билет в кармане?", "Почему дедушка хранит этот билет?")),
        ComprehensionStory(id = "4_23", grade = 4, title = "Не только слова", text = "В школе мы проходили тему о том, как важно общаться. Учительница сказала, что общение — это не только слова. Однажды я сам убедился в этом. Мой друг Петя проиграл в шахматы и был очень расстроен. Он ни слова не говорил, но я видел, как он нахмурился и опустил плечи. Я не стал его утешать словами. Я просто подошел, сел рядом и похлопал его по плечу. Петя вздохнул и улыбнулся мне. В этот момент я понял, что иногда молчаливая поддержка и понимание значат гораздо больше, чем любые длинные речи. Настоящий друг чувствует настроение без лишних слов.", questions = listOf("Какую тему проходили в школе?", "Что случилось с другом?", "Почему Петя был расстроен?", "Как мальчик поддержал друга?", "Что понял мальчик о поддержке?")),
        ComprehensionStory(id = "4_24", grade = 4, title = "Рисунок скамейки", text = "Наш двор очень красивый, но в нем есть старая деревянная скамейка. Она выглядела совсем невзрачно. Однажды мы с друзьями решили украсить её. Мы принесли краски и кисточки. Мы раскрасили скамейку в яркие цвета и нарисовали на ней цветы и солнце. Теперь это самое популярное место во дворе. Возле нее всегда кто-то сидит: бабушки отдыхают, дети рисуют. Я очень рад, что мы смогли сделать наш двор чуть-чуть лучше своими руками.", questions = listOf("Какая скамейка была во дворе?", "Что решили сделать дети?", "Чем они украсили скамейку?", "Кто теперь сидит на скамейке?", "Чему радуется мальчик?")),
        ComprehensionStory(id = "4_25", grade = 4, title = "Письма по порядку", text = "Моя бабушка хранит все письма, которые ей присылают. Она складывает их в хронологическом порядке в большую коробку. Когда я прихожу к ней в гости, она достает эту коробку. Мы вместе читаем письма от ее старых друзей. Это как путешествие во времени. Мы читаем о том, как они ездили на море, как отмечали праздники. Бабушка говорит, что эти письма — это история ее жизни. Я очень люблю слушать эти истории. Теперь я тоже начал писать ей письма, когда уезжаю. И она складывает их в коробку по порядку.", questions = listOf("Что хранит бабушка?", "В каком порядке она складывает письма?", "Что бабушка и внук делают вместе?", "Почему письма — это путешествие во времени?", "Что начал делать мальчик?")),
    )

    fun getStoriesByGrade(grade: Int): List<ComprehensionStory> {
        return stories.filter { it.grade == grade }
    }

    fun getRandomStory(grade: Int): ComprehensionStory? {
        val list = getStoriesByGrade(grade)
        if (list.isEmpty()) return null
        return list.random()
    }
}
